import SwiftUI
struct TasksView:View{@EnvironmentObject var s:AppStore;@State var add=false;var body:some View{NavigationStack{List{ForEach(s.tasks){t in HStack{Button{s.completeTask(t)}label:{Image(systemName:t.isCompleted ? "checkmark.circle.fill":"circle")}.buttonStyle(.borderless);VStack(alignment:.leading){Text(t.title).strikethrough(t.isCompleted);Text("\(t.durationMinutes) min • \(t.priority.rawValue)").font(.caption)}}}.onDelete{for i in $0{s.deleteTask(s.tasks[i])}}}.navigationTitle("Tasks").toolbar{Button{add=true}label:{Image(systemName:"plus")}}.sheet(isPresented:$add){AddTask()}}}}
struct AddTask:View{@EnvironmentObject var s:AppStore;@Environment(\.dismiss)var dismiss;@State var n="";@State var d=30;@State var p:UUID?;@State var q=TaskPriority.medium;var body:some View{NavigationStack{Form{TextField("Task",text:$n);Picker("Duration",selection:$d){ForEach([15,30,45,60,90],id:\.self){Text("\($0) minutes")}};Picker("Project",selection:$p){Text("None").tag(UUID?.none);ForEach(s.projects.filter{!$0.isClosed}){Text($0.name).tag(Optional($0.id))}};Picker("Priority",selection:$q){ForEach(TaskPriority.allCases){Text($0.rawValue).tag($0)}}}.navigationTitle("New Task").toolbar{ToolbarItem(placement:.cancellationAction){Button("Cancel"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Add"){s.addTask(n,d,p,q);dismiss()}.disabled(n.isEmpty)}}}}}